/** Local maxima that clear the mean by a margin — used to call something a "wave". */
export function countWaves(series: number[], window = 12) {
  const m = mean(series);
  if (m <= 0) return 0;
  let count = 0;
  for (let i = window; i < series.length - window; i++) {
    const v = series[i];
    if (v <= m * 1.12) continue;
    let peak = true;
    for (let k = 1; k <= window; k++) {
      if (series[i - k] > v || series[i + k] > v) {
        peak = false;
        break;
      }
    }
    if (peak) {
      count++;
      i += window;
    }
  }
  return count;
}

