input.content:
:root {
  --bg: #f2f6ee;
  --panel: #ffffff;
  --ink: #223229;
  --muted: #6b7f72;
  --line: #dde6dc;
  --blue: #3f8fdb;
  --red: #e2604a;
  --fruit: #5aa03c;
  --accent: #2f7a41;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: radial-gradient(circle at 20% 0%, #ffffff, var(--bg) 60%);
  color: var(--ink);
  font: 14px/1.45 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

button {
  font: inherit;
  color: inherit;
}

.app {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px 18px 28px;
  max-width: 1560px;
  margin: 0 auto;
}

.masthead {
  display: flex;
  align-items: baseline;
  gap: 14px;
  flex-wrap: wrap;
}

.masthead h1 {
  margin: 0;
  font-size: 26px;
  letter-spacing: -0.02em;
  font-weight: 700;
}

.masthead .clock {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 332px;
  gap: 14px;
  align-items: start;
}

@media (max-width: 1080px) {
  .layout {
    grid-template-columns: minmax(0, 1fr);
  }
}

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(31, 58, 44, 0.06), 0 12px 30px -22px rgba(31, 58, 44, 0.5);
}

.card > h2 {
  margin: 0;
  padding: 12px 14px 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.stage {
  position: relative;
  overflow: hidden;
  padding: 0;
}

.stage canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}

.stage canvas.dragging {
  cursor: grabbing;
}

.stage-wrap {
  position: relative;
  height: min(62vh, 620px);
  min-height: 380px;
}

.hud {
  position: absolute;
  top: 10px;
  left: 10px;
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  pointer-events: none;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.88);
  border: 1px solid rgba(31, 58, 44, 0.1);
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 6px 14px -10px rgba(31, 58, 44, 0.8);
}

.dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.hint {
  position: absolute;
  right: 10px;
  bottom: 10px;
  font-size: 11px;
  color: #3d5a49;
  background: rgba(255, 255, 255, 0.8);
  padding: 3px 9px;
  border-radius: 999px;
  pointer-events: none;
}

.transport {
  display: flex;
  gap: 8px;
  padding: 10px 12px;
  border-top: 1px solid var(--line);
  flex-wrap: wrap;
}

.btn {
  border: 1px solid var(--line);
  background: #fff;
  padding: 7px 13px;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 600;
  font-size: 13px;
  transition: background 0.15s, border-color 0.15s, transform 0.06s;
}

.btn:hover {
  background: #f4f9f2;
  border-color: #c3d6c4;
}

.btn:active {
  transform: translateY(1px);
}

.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: #276936;
}

.btn:disabled {
  opacity: 0.45;
  cursor: default;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.presets {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 12px 12px;
}

.preset {
  text-align: left;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 11px;
  padding: 8px 11px;
  cursor: pointer;
}

.preset:hover {
  border-color: #b9d3bb;
  background: #f6fbf4;
}

.preset.on {
  border-color: var(--accent);
  background: #eef7ee;
}

.preset b {
  display: block;
  font-size: 13px;
}

.preset span {
  color: var(--muted);
  font-size: 11.5px;
}

.controls {
  padding: 0 12px 12px;
  max-height: 46vh;
  overflow-y: auto;
}

.group-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 12px 0 6px;
  display: flex;
  align-items: center;
  gap: 7px;
}

.ctl {
  margin-bottom: 9px;
}

.ctl-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  font-size: 12.5px;
}

.ctl-head b {
  font-weight: 600;
}

.ctl-head .val {
  font-variant-numeric: tabular-nums;
  color: var(--accent);
  font-weight: 700;
}

.ctl-hint {
  font-size: 11px;
  color: var(--muted);
}

.ctl input[type="range"] {
  width: 100%;
  margin: 2px 0 0;
  accent-color: var(--accent);
}

.tag {
  font-size: 9.5px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #97684a;
  background: #fbf0e6;
  border-radius: 5px;
  padding: 1px 5px;
  font-weight: 700;
}

.inspector {
  padding: 0 14px 14px;
}

.rows {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  font-size: 12.5px;
}

.rows dt {
