  padding: 0;
}

.stage canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}

.stage canvas.dragging {
  cursor: grabbing;
}

.stage-wrap {
  position: relative;
  height: min(62vh, 620px);
  min-height: 380px;
}

.hud {
  position: absolute;
  top: 10px;
  left: 10px;
  display: flex;
  gap: 6px;
