/**
 * Drives the running dev server in headless Chrome over CDP: waits for real
 * animation frames, clicks a blob, drags the dish, switches presets, and reports
 * every console error / uncaught exception it saw.
 */
import { spawn } from "node:child_process";
import { writeFileSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const URL_APP = process.argv[2] ?? "http://localhost:9220/";
const OUT = process.argv[3] ?? ".";
const PORT = 9333;
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const profile = mkdtempSync(join(tmpdir(), "cdp-"));
const chrome = spawn(CHROME, [
  "--headless=new",
  "--disable-gpu",
  `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${profile}`,
  "--window-size=1500,1600",
  "--hide-scrollbars",
  "about:blank",
]);
chrome.stderr.on("data", () => {});

let target = null;
for (let i = 0; i < 60 && !target; i++) {
  await sleep(250);
  try {
    const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
    target = list.find((t) => t.type === "page");
  } catch {}
}
if (!target) {
  console.log("FAIL: no chrome target");
  chrome.kill();
  process.exit(1);
}

const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));

let nextId = 1;
const pending = new Map();
const problems = [];
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
    return;
  }
  if (msg.method === "Runtime.exceptionThrown") {
    const d = msg.params.exceptionDetails;
    problems.push(`EXCEPTION ${d.text} ${d.exception?.description ?? ""}`.slice(0, 400));
  }
  if (msg.method === "Runtime.consoleAPICalled" && ["error", "warning"].includes(msg.params.type)) {
    problems.push(
      `CONSOLE.${msg.params.type} ${msg.params.args
        .map((a) => a.value ?? a.description ?? a.type)
        .join(" ")}`.slice(0, 400),
    );
  }
};

function send(method, params = {}) {
  const id = nextId++;
  return new Promise((resolve) => {
    pending.set(id, (m) => resolve(m.result ?? m.error));
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(expr) {
  const r = await send("Runtime.evaluate", {
    expression: expr,
    returnByValue: true,
    awaitPromise: true,
  });
  if (r.exceptionDetails) {
    problems.push(`EVAL ${r.exceptionDetails.text}`);
    return null;
  }
  return r.result?.value;
}

async function shot(name) {
  const r = await send("Page.captureScreenshot", { format: "png" });
  if (r?.data) writeFileSync(join(OUT, name), Buffer.from(r.data, "base64"));
}

async function mouse(type, x, y, extra = {}) {
  await send("Input.dispatchMouseEvent", {
    type,
    x,
    y,
    button: "left",
    buttons: type === "mouseReleased" ? 0 : 1,
    clickCount: 1,
    pointerType: "mouse",
    ...extra,
  });
}

await send("Runtime.enable");
await send("Page.enable");
await send("Log.enable");
await send("Page.navigate", { url: URL_APP });
await sleep(2500);

const report = {};
report.title = await evaluate("document.title");
report.h1 = await evaluate("document.querySelector('h1').textContent");

// --- 1. does the simulation actually advance on real animation frames? ---
const t0 = await evaluate("document.querySelector('.clock').textContent");
await sleep(9000);
const t1 = await evaluate("document.querySelector('.clock').textContent");
report.clockStart = t0;
report.clockAfter9s = t1;
report.advanced = t0 !== t1;
report.chartPathLen = await evaluate(
  "document.querySelectorAll('.chart-body path')[1]?.getAttribute('d')?.length ?? 0",
);
report.summary = await evaluate("document.querySelector('.headline')?.textContent");
report.counts = await evaluate(
  "[...document.querySelectorAll('.pill')].map(p=>p.textContent).join(' | ')",
);

// --- 2. click a blob: probe a grid until the inspector fills in ---
const rect = await evaluate(
  "(()=>{const r=document.querySelector('canvas').getBoundingClientRect();return {x:r.left,y:r.top,w:r.width,h:r.height}})()",
);
let picked = null;
outer: for (let gy = 0.3; gy <= 0.75 && !picked; gy += 0.045) {
  for (let gx = 0.25; gx <= 0.8; gx += 0.035) {
    const x = rect.x + rect.w * gx;
    const y = rect.y + rect.h * gy;
    await mouse("mousePressed", x, y);
    await mouse("mouseReleased", x, y);
    const rows = await evaluate(
      "document.querySelector('.inspector .rows') ? document.querySelector('.inspector').innerText.replace(/\\n/g,' | ') : ''",
    );
    if (rows) {
      picked = rows;
      break outer;
    }
  }
}
report.inspector = picked ? picked.slice(0, 340) : "NO BLOB PICKED";
await shot("shot-selected.png");

// --- 3. drag to spin the dish ---
const cx = rect.x + rect.w / 2;
const cy = rect.y + rect.h / 2;
const before = await evaluate(
  "(()=>{const c=document.querySelector('canvas');return c.getContext('2d').getImageData(c.width*0.5,c.height*0.35,1,1).data.join(',')})()",
);
await mouse("mousePressed", cx, cy);
for (let i = 1; i <= 12; i++) await mouse("mouseMoved", cx + i * 14, cy);
await mouse("mouseReleased", cx + 168, cy);
await sleep(600);
const after = await evaluate(
  "(()=>{const c=document.querySelector('canvas');return c.getContext('2d').getImageData(c.width*0.5,c.height*0.35,1,1).data.join(',')})()",
);
report.dragChangedPixels = before !== after;

// --- 4. presets + sliders ---
await evaluate(
  "[...document.querySelectorAll('.preset')].find(b=>b.textContent.includes('Low-fruit')).click()",
);
await sleep(1200);
report.afterPreset = await evaluate(
  "[...document.querySelectorAll('.pill')].map(p=>p.textContent).join(' | ')",
);
report.presetActive = await evaluate(
  "document.querySelector('.preset.on')?.textContent?.slice(0,20)",
);
report.lowFruitSliders = await evaluate(
  "[...document.querySelectorAll('.ctl')].slice(0,3).map(c=>c.querySelector('.val').textContent).join(' / ')",
);

// pause / step / play
await evaluate("[...document.querySelectorAll('.btn')].find(b=>b.textContent==='Pause').click()");
await sleep(400);
const paused = await evaluate("document.querySelector('.clock').textContent");
await sleep(1200);
report.pausedHolds = paused === (await evaluate("document.querySelector('.clock').textContent"));
await evaluate("[...document.querySelectorAll('.btn')].find(b=>b.textContent==='Step').click()");
await sleep(300);
report.stepMoved = paused !== (await evaluate("document.querySelector('.clock').textContent"));
await evaluate("[...document.querySelectorAll('.btn')].find(b=>b.textContent==='Play').click()");

// a reset-key slider must rebuild the world
await evaluate(`(()=>{
  const el=document.getElementById('ctl-worldSize');
  const set=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
  set.call(el,'52');
  el.dispatchEvent(new Event('input',{bubbles:true}));
})()`);
await sleep(900);
report.afterWorldSize = await evaluate("document.querySelector('.clock').textContent");
await shot("shot-lowfruit.png");

// --- 5. back to balanced, let it run long enough to show waves ---
await evaluate(
  "[...document.querySelectorAll('.preset')].find(b=>b.textContent.includes('Balanced')).click()",
);
await evaluate(`(()=>{
  const el=document.getElementById('ctl-simSpeed');
  const set=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
  set.call(el,'12');
  el.dispatchEvent(new Event('input',{bubbles:true}));
})()`);
await sleep(30000);
report.longRun = await evaluate("document.querySelector('.clock').textContent");
report.longCounts = await evaluate(
  "[...document.querySelectorAll('.pill')].map(p=>p.textContent).join(' | ')",
);
report.longSummary = await evaluate(
  "document.querySelector('.summary')?.innerText?.replace(/\\n/g,' | ')?.slice(0,420)",
);
report.stats = await evaluate(
  "[...document.querySelectorAll('.stat')].map(s=>s.innerText.replace(/\\n/g,' ')).join(' · ')",
);
await shot("shot-long.png");
await evaluate("window.scrollTo(0,document.body.scrollHeight)");
await sleep(500);
await shot("shot-charts.png");

report.problems = problems.slice(0, 12);
console.log(JSON.stringify(report, null, 2));
ws.close();
chrome.kill();

